import{c as e,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"研究主題：大道至簡 — Claude Cost & Efficiency 最佳實踐","description":"","frontmatter":{"date":"2026-05-12T00:00:00.000Z","depth":"D2","sources":"research/papers/ + research/tweets/ + research/best-practices/","topic":"大道至簡 — Claude Best Practices / Cost & Efficiency Optimization","verify":"V1+V2"},"headers":[],"relativePath":"research/reports/archive/2026-05-12-best-practices-simplicity.md","filePath":"research/reports/archive/2026-05-12-best-practices-simplicity.md","lastUpdated":1780842316000}'),i={name:"research/reports/archive/2026-05-12-best-practices-simplicity.md"};function n(s,t,d,l,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="研究主題-大道至簡-—-claude-cost-efficiency-最佳實踐" tabindex="-1">研究主題：大道至簡 — Claude Cost &amp; Efficiency 最佳實踐 <a class="header-anchor" href="#研究主題-大道至簡-—-claude-cost-efficiency-最佳實踐" aria-label="Permalink to &quot;研究主題：大道至簡 — Claude Cost &amp; Efficiency 最佳實踐&quot;">​</a></h1><h2 id="信度分層摘要" tabindex="-1">信度分層摘要 <a class="header-anchor" href="#信度分層摘要" aria-label="Permalink to &quot;信度分層摘要&quot;">​</a></h2><h3 id="o-官方-anthropic-一手資料" tabindex="-1">[O] 官方 / Anthropic 一手資料 <a class="header-anchor" href="#o-官方-anthropic-一手資料" aria-label="Permalink to &quot;[O] 官方 / Anthropic 一手資料&quot;">​</a></h3><ul><li><strong>CLAUDE.md budget</strong>: bcherny 明示 ≤60 行最佳，≤200 行上限。超過後模型注意力稀釋 → 有效規則密度下降。</li><li><strong>Prompt Caching 五原則</strong>（bcherny）：Static first, dynamic last；工具列表與模型 mid-session 不可改；<code>defer_loading: true</code> 保持 cache prefix 穩定。Cache hit = 0.1× 費率，write = 1.25× 費率。</li><li><strong>Context Engineering</strong>（Karpathy）：「填充恰好所需的資訊」是核心；too much context = 成本上升 + 品質下降，不是越多越好。</li><li><strong>Output Discipline 實測</strong>：英文 -80.6%、繁中 -86.2% 輸出 token，LLM Judge 品質無衰退（T-B/T-C/T-D 驗證 2026-04-30）。</li></ul><h3 id="c-社群觀察-未官方確認" tabindex="-1">[C] 社群觀察（未官方確認） <a class="header-anchor" href="#c-社群觀察-未官方確認" aria-label="Permalink to &quot;[C] 社群觀察（未官方確認）&quot;">​</a></h3><ul><li><strong>Contextmaxxing vs Tokenmaxxing</strong>（ashwingop/Sentra）：compiled memory 可減少 50–98% token；「right context &gt; more context」。⚠️ 幅度數字為特定應用實測，不可直接套用。</li><li><strong>Tool saturation</strong>（nicbstme）：~20 工具飽和閾值；combined agents+MCP 約 15。超過後 routing 精度明顯下降。</li><li><strong>AgentOpt</strong>（P-tier 研究）：Weak planner + strong solver pattern → 13–32× 成本差距。</li><li><strong>Context rot 閾值</strong>（Thariq @trq212）：約 300–400k tokens 開始影響輸出品質。⚠️ 社群觀察，高度任務依賴。</li></ul><h3 id="e-行業報告" tabindex="-1">[E] 行業報告 <a class="header-anchor" href="#e-行業報告" aria-label="Permalink to &quot;[E] 行業報告&quot;">​</a></h3><ul><li><strong>DeepMind 多代理協調研究（2025）</strong>：Baseline &gt; 80% 加代理反降性能；Coordination Tax 在 ≥4 agents 飽和；Bag-of-Agents 17.2× 錯誤放大。</li></ul><h2 id="來源驗證結果" tabindex="-1">來源驗證結果 <a class="header-anchor" href="#來源驗證結果" aria-label="Permalink to &quot;來源驗證結果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Claim</th><th>來源層</th><th>狀態</th><th>備注</th></tr></thead><tbody><tr><td>≤60 行 optimal CLAUDE.md</td><td>O (bcherny)</td><td>✅ confirmed</td><td>cc-workspace CLAUDE.md 81 行，超過但在 200 行預算內</td></tr><tr><td>Prompt caching 0.1× hit rate</td><td>O (Anthropic docs)</td><td>✅ confirmed</td><td>官方定價頁</td></tr><tr><td>-80.6% output token</td><td>O (內部實測)</td><td>✅ confirmed</td><td>output-discipline.md 已實作</td></tr><tr><td>Tool saturation ~20</td><td>C (nicbstme)</td><td>⚠️ unverified</td><td>單一社群觀察，無 replications</td></tr><tr><td>Context rot 300-400k</td><td>C (Thariq)</td><td>⚠️ unverified</td><td>社群觀察，任務高度依賴</td></tr><tr><td>50-98% token 節省</td><td>C (ashwingop)</td><td>⚠️ unverified</td><td>特定應用，幅度不通用</td></tr></tbody></table><h2 id="大道至簡核心發現" tabindex="-1">大道至簡核心發現 <a class="header-anchor" href="#大道至簡核心發現" aria-label="Permalink to &quot;大道至簡核心發現&quot;">​</a></h2><h3 id="主論點" tabindex="-1">主論點 <a class="header-anchor" href="#主論點" aria-label="Permalink to &quot;主論點&quot;">​</a></h3><p><strong>加法思維是效率陷阱</strong>。研究一致指向：更少的、更精確的 context &gt; 更多的 context；更強的 prompt &gt; 更多的 agent；更好的工具設計 &gt; 更多的工具。</p><h3 id="量化基準-本-workspace-套用" tabindex="-1">量化基準（本 workspace 套用） <a class="header-anchor" href="#量化基準-本-workspace-套用" aria-label="Permalink to &quot;量化基準（本 workspace 套用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指標</th><th>前（本次研究前）</th><th>後（本次改動）</th><th>來源</th></tr></thead><tbody><tr><td>subagent-strategy.md 行數</td><td>137 行</td><td>91 行 (−34%)</td><td>本次 prune pass</td></tr><tr><td>Auto-loaded rules 總行數</td><td>348 行</td><td>~302 行</td><td>本次 prune pass</td></tr><tr><td>PermissionRequest 審計覆蓋</td><td>無</td><td>有 (audit-permission.sh)</td><td>上一 session 補充</td></tr><tr><td>Tool schema lint</td><td>無</td><td>有 (session-init.sh)</td><td>上一 session 補充</td></tr><tr><td>Compact hint 指引</td><td>無</td><td>有 (context-management.md)</td><td>上一 session 補充</td></tr></tbody></table><h3 id="大道至簡-prune-test-應用於本-workspace" tabindex="-1">大道至簡 Prune Test（應用於本 workspace） <a class="header-anchor" href="#大道至簡-prune-test-應用於本-workspace" aria-label="Permalink to &quot;大道至簡 Prune Test（應用於本 workspace）&quot;">​</a></h3><p><strong>測試問題</strong>：「移除這條規則，過去是否會發生具體失敗？」</p><table tabindex="0"><thead><tr><th>移除內容</th><th>Pass test?</th><th>行動</th></tr></thead><tbody><tr><td>45% 規則完整表格（30 行）</td><td>✅ 可移除</td><td>壓縮為 1 行摘要 + ref 指標</td></tr><tr><td>5D Coordination Layer 規格表</td><td>✅ 可移除</td><td>行為約束已在 7-row topology 表內</td></tr><tr><td>任務-拓撲匹配完整表格</td><td>✅ 可移除</td><td>PlanCraft -39% 已在 Known Gotchas 保留</td></tr><tr><td>&quot;跳過 45% 量化&quot; gotcha</td><td>✅ 可移除</td><td>與壓縮後摘要重複</td></tr><tr><td>生產環境安全紅線</td><td>❌ 不可移除</td><td>高風險操作必要約束</td></tr><tr><td>Git commit session URL 強制</td><td>❌ 不可移除</td><td>無 hook 時容易漏，hook 也依賴規則提醒</td></tr><tr><td>Monitor 策略</td><td>❌ 不可移除</td><td>不設會造成長時間無回應</td></tr></tbody></table><h2 id="架構建議-下一步-非本次實作" tabindex="-1">架構建議（下一步 / 非本次實作） <a class="header-anchor" href="#架構建議-下一步-非本次實作" aria-label="Permalink to &quot;架構建議（下一步 / 非本次實作）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>優先序</th><th>建議</th><th>預期效益</th><th>複雜度</th></tr></thead><tbody><tr><td>A1</td><td>Memory Layering：區分 session memory / project memory / global memory</td><td>減少 session 載入 token</td><td>中</td></tr><tr><td>A2</td><td>Semantic Compact hint 模板：為常見任務類型預建 compact hint</td><td>減少 Lost-in-Middle 損耗</td><td>低</td></tr><tr><td>A3</td><td>AgentOpt 模式：識別 planner vs solver 分離點，降級 planner 模型</td><td>13–32× 成本差距</td><td>高</td></tr></tbody></table><h2 id="輸出建議" tabindex="-1">輸出建議 <a class="header-anchor" href="#輸出建議" aria-label="Permalink to &quot;輸出建議&quot;">​</a></h2><ul><li>本次研究 → <strong>已實作</strong>（prune pass 完成，見上表）</li><li>A1-A3 → <strong>未來 session</strong>，複雜度較高，需單獨規劃</li></ul><hr><p><em>驗證：V1 self-check 完成（所有 claim 有標注）；V2 cross-check：output-discipline 實測數字來自同 workspace 驗證，可信度高。</em></p><hr><h2 id="最終論-final-pass-—-2026-05-12" tabindex="-1">最終論（Final Pass）— 2026-05-12 <a class="header-anchor" href="#最終論-final-pass-—-2026-05-12" aria-label="Permalink to &quot;最終論（Final Pass）— 2026-05-12&quot;">​</a></h2><p>三向平行 researcher（best-practices/papers/tweets）再次掃描，共發現 6 個候選 gap，advisor 逐項裁決：</p><table tabindex="0"><thead><tr><th>Gap</th><th>裁決</th><th>原因（prune test）</th></tr></thead><tbody><tr><td>CLAUDE.md 自更新 prompt suffix</td><td>REJECT</td><td>core.md 已有犯錯記錄原則；遞迴 meta-bloat</td></tr><tr><td>Permission Hook Opus 自動核准</td><td>REJECT</td><td>solo interactive：Opus roundtrip 5–10s &gt; 人工 1s；未來 batch 模式再評估</td></tr><tr><td>Dreaming / Offline Learning</td><td>REJECT</td><td>誤機制：dreaming 是 online agent，非 session-stop logger；人工 Known Gotcha = 正確替代</td></tr><tr><td><code>--from-pr</code> PR 恢復</td><td>REJECT</td><td>CLI feature，非行為規則；需要時加入 playbook 即可</td></tr><tr><td>Keep Rate 度量</td><td>REJECT</td><td>logging ≠ closed-loop；solo workspace 無品質退化未被發現的歷史證據</td></tr><tr><td>TSCG Tool Schema 壓縮</td><td>DEFER</td><td>觸發條件（&gt;10 MCP tools）未滿足；條件滿足時重新評估</td></tr></tbody></table><p><strong>Advisor meta-verdict</strong>：優化已達穩態。下一條有價值的規則來自「實際使用中發現規則失效」，而非再一輪研究掃描。宣告大道至簡優化完成。</p><hr><p><em>🔄 overnight-research 驗證：2026-05-23 — 本文件為 workspace 內部分析（tweets/best-practices 本地資料），不依賴可即時更新的外部官方資料。狀態：已確認現行有效。</em></p><hr><h2 id="_2026-05-25-re-check" tabindex="-1">2026-05-25 Re-check <a class="header-anchor" href="#_2026-05-25-re-check" aria-label="Permalink to &quot;2026-05-25 Re-check&quot;">​</a></h2><blockquote><p><strong>方法</strong>：對照 <code>.claude/rules/</code> 4 個 auto-load 規則的現狀，核查大道至簡原則在架構建議（A1–A3）的落地情況，並結合 <code>2026-05-25-papers-analysis.md</code> 新論文驗證核心主張。</p></blockquote><h3 id="已落地的建議-✅" tabindex="-1">已落地的建議（✅） <a class="header-anchor" href="#已落地的建議-✅" aria-label="Permalink to &quot;已落地的建議（✅）&quot;">​</a></h3><p><strong>核心主張驗證</strong></p><ul><li>✅ CLAUDE.md ≤ 200 行上限：workspace CLAUDE.md 已控制在預算內（4 個 auto-load 規則 + 參照格式，符合 ≤200 行設計）</li><li>✅ Prompt Caching 三禁止：<code>context-management.md</code> 已明文（mid-session 禁止切換模型/工具/CLAUDE.md）</li><li>✅ Output Discipline 實測（英文 -80.6%、繁中 -86.2%）：<code>output-discipline.md</code> 已完整實作，無開場白 + 填充語禁止 + ≤150 字上限</li><li>✅ Compact 三層觸發（行為信號 &gt; 數字閾值 &gt; 定時器）：<code>context-management.md</code> 已落地</li><li>✅ Compact hint 格式（保留安全紅線 / 專案慣例 / 關鍵假設；捨棄中間詳情）：<code>context-management.md</code> 已明文</li><li>✅ PermissionRequest 審計（<code>audit-permission.sh</code>）：已在 hooks 目錄實作</li><li>✅ Tool schema lint（<code>session-init.sh</code>）：已在 hooks 目錄實作</li><li>✅ 「移除這條規則，過去是否會發生具體失敗？」剪枝測試：<code>core.md</code> §Framework Integrity 已制度化</li></ul><p><strong>Prune Test 裁決追蹤</strong></p><ul><li>✅ 生產環境安全紅線「不可移除」：<code>core.md</code> 已保留（GCP/TF/K8s 含 prod）</li><li>✅ Monitor 策略「不可移除」：<code>core.md</code> §長任務執行 已保留（Bash &gt;30s → Monitor + run_in_background）</li><li>✅ Git commit session URL 強制「不可移除」：<code>core.md</code> §Git 工作流程 已保留</li></ul><p><strong>架構建議（A1–A3）</strong></p><ul><li>✅ A1 Memory Layering：<code>core.md</code> §長期記憶回路 雙層架構（Auto Memory + MEMORY.md）已落地；<code>refs/memory-layering.md</code> 已建立</li><li>✅ A2 Semantic Compact hint 模板：<code>context-management.md</code> 已有 compact hint 格式規範</li><li>⚠️ A3 AgentOpt（planner vs solver 分離）：<code>subagent-strategy.md</code> 已有模型分層（Haiku executor / Sonnet / Opus），但「降級 planner 模型」的系統化識別流程未完整落地</li></ul><h3 id="待追蹤的-gap-⚠️" tabindex="-1">待追蹤的 gap（⚠️） <a class="header-anchor" href="#待追蹤的-gap-⚠️" aria-label="Permalink to &quot;待追蹤的 gap（⚠️）&quot;">​</a></h3><ul><li>⚠️ <strong>A3 AgentOpt 模式未完全落地</strong>：<code>subagent-strategy.md</code> 的模型選擇以「獨立檔案數」為主要判斷依據（0–1 Haiku / 2–9 Sonnet / 10+ Sonnet/Opus），但 AgentOpt 的「強 solver + 弱 planner」模式（讓 Haiku/Sonnet 規劃，Opus 執行複雜決策）尚未系統化。2026-05-25 論文分析進一步驗證此模式：強模型當 Planner 在某些場景反而降低整體表現。</li><li>⚠️ <strong>Tool saturation ~20 工具閾值仍未驗證</strong>：本報告標注「⚠️ 社群觀察，無 replications」。截至 2026-05-25，workspace MCP server 數量持續增長（Google Drive、GitHub 等），但未追蹤當前實際 MCP tools 總數，不確定是否已接近 ~15（combined agents+MCP）飽和閾值。</li><li>⚠️ <strong>TSCG Tool Schema 壓縮（DEFER 項目）</strong>：最終論裁決「條件滿足時重新評估」。<code>2026-05-25-papers-analysis.md</code> 中 <code>tscg-tool-schema-compilation</code> 論文實測工具模式 52-57% token 節省（Phi-4 從 0%→84.4%）。隨 MCP 工具增長，此 DEFER 項目的評估條件（&gt;10 MCP tools）可能已接近。需重新評估是否觸發。</li><li>⚠️ <strong>Context rot 閾值 300-400k token（⚠️ 社群觀察）</strong>：<code>context-management.md</code> 已採用此閾值作為「定時器」觸發條件，但本報告標注信度為 [C]（未官方確認）。2026-05 論文未提供更精確的實驗數據，仍需觀察。</li></ul><h3 id="新發現的最佳實踐補充-🆕" tabindex="-1">新發現的最佳實踐補充（🆕） <a class="header-anchor" href="#新發現的最佳實踐補充-🆕" aria-label="Permalink to &quot;新發現的最佳實踐補充（🆕）&quot;">​</a></h3><ul><li>🆕 <strong>「right context &gt; more context」獲論文級驗證</strong>：本報告的核心主張「加法思維是效率陷阱」獲 2026-05-25 論文分析強力支持。<code>natural-language-agent-harnesses-2603-25723</code> 實測 NLAH 將 context 從 60.1K → 2.9K token（-95%），效能相當。「填充恰好所需資訊」不再只是經驗法則，而有論文級量化驗證。</li><li>🆕 <strong>「Harness &gt; 模型」對大道至簡的啟示</strong>：論文分析的核心發現「Harness 配置效益超越模型升級」是大道至簡在 AI 編程領域最強的外部驗證：與其升級模型（花費）不如優化 CLAUDE.md + Hooks + Memory 設計（免費）。本報告的「加法思維是效率陷阱」獲得了更廣泛的框架支持。</li><li>🆕 <strong>Bayesian 優化 vs 手工調優的量化反差</strong>：<code>harbor-automated-harness-optimization</code> 論文：Bayesian 優化 9 個配置旗標明顯優於手工調優，且手工調優可能產生退化（-37%）。這是 A3 AgentOpt 模式的新佐證：planner/solver 分工的最優邊界不應靠直覺手工設定，而需要系統性搜索。</li><li>🆕 <strong><code>/goal</code> 命令作為大道至簡的工具化</strong>：<code>/goal</code> 讓 Claude 迭代到達標（R4），減少人工介入的「你完成了嗎？」確認輪次。對需要多輪執行的任務，<code>/goal</code> 是 context 效率的提升工具（減少 prompt 往返）。與大道至簡原則高度契合：一次設定終止條件，而非多次手動 checkpoint。</li><li>🆕 <strong>Sub-agent progress summaries 的 cache 命中（v2.1.128）</strong>：長 agentic 任務的 cache creation token 成本降低約 3×。本報告 §量化基準表格應更新：原先計算 agentic 任務成本的基準假設已不再準確，實際成本低於估算。</li></ul><h3 id="_2026-06-05-增量併入-窄-gap-1-條真補充" tabindex="-1">2026-06-05 增量併入（窄 gap，1 條真補充） <a class="header-anchor" href="#_2026-06-05-增量併入-窄-gap-1-條真補充" aria-label="Permalink to &quot;2026-06-05 增量併入（窄 gap，1 條真補充）&quot;">​</a></h3><blockquote><p>此報告已多輪 re-check，gap 較窄。本次逐 2 篇候選論文校準：TSCG DEFER 無實質 gap（只更日期）、ACE brevity bias 1 條真 gap。</p></blockquote><ul><li>🆕 <strong>「大道至簡」有下限：brevity bias 在 knowledge-intensive 任務反傷效能</strong>（ACE / ICLR 2026，arXiv:2510.04618）：前代 context 適應方法普遍患 brevity bias——為精簡摘要而丟棄 domain-specific heuristics（verbatim：&quot;brevity bias, which drops domain insights for concise summaries&quot;，2025-10-06-agentic-context-engineering…md L18）。ACE Key Takeaway #1：「Context adaptation ≠ context compression: Growing a structured playbook outperforms repeatedly rewriting and shrinking it」（同檔 L147）。<strong>對大道至簡的精化</strong>：去除 redundancy（✅ 正確）≠ 削減 domain insight（⚠️ 知識密集場景反降效能）。簡潔下限 = 保留 task-critical heuristics。⚠️ 接地警示：ACE −82.6% 是 KV cache <strong>billed cost reduction</strong>（同檔 L112，命中率 91.8%），<strong>非</strong> brevity/簡潔幅度，不可誤植為「精簡帶來 −82.6%」。</li><li><strong>TSCG DEFER 現況</strong>：條件門檻「&gt;10 MCP tools」接近但未確認觸發——workspace MCP（Google Drive / GitHub）持續增長但未追蹤實際 tools 總數。論文數據（52–57% token 節省，Phi-4 0%→84.4%）前文已準確引用，無新 gap，僅更新 re-check 日期。</li></ul><p><em>Re-check 日期：2026-06-05 | 核心結論：「大道至簡」主張獲 2026 論文級驗證，A1/A2 已落地，A3 部分落地；新增 ACE「簡潔有下限」精化；TSCG DEFER 條件接近觸發（MCP 計數待確認）</em></p><hr><h2 id="_2026-06-05-增量併入-gap-vote-三技能共識-5-真-gap-1-既有段佐證" tabindex="-1">2026-06-05 增量併入（gap-vote 三技能共識，5 真 gap + 1 既有段佐證） <a class="header-anchor" href="#_2026-06-05-增量併入-gap-vote-三技能共識-5-真-gap-1-既有段佐證" aria-label="Permalink to &quot;2026-06-05 增量併入（gap-vote 三技能共識，5 真 gap + 1 既有段佐證）&quot;">​</a></h2><blockquote><p><strong>方法</strong>：gap-vote（research-hub / overnight-research / autoresearch:reason 三角色並行）對近期 corpus（76 篇 md）找未併入 gap，2/3 共識 confirm + <strong>主對話親自 grep 重驗每數字 + verbatim</strong>（subagent verdict 非證據）。本報告分得「大道至簡 / 成本效率 / 模型選擇」相關 gap，集中於此段。</p></blockquote><h3 id="補充-a-overthinking-tax——冗長輸出的經濟學接地-ockbench-arxiv-2511-05722" tabindex="-1">補充 A：Overthinking Tax——冗長輸出的經濟學接地（OckBench，arXiv:2511.05722） <a class="header-anchor" href="#補充-a-overthinking-tax——冗長輸出的經濟學接地-ockbench-arxiv-2511-05722" aria-label="Permalink to &quot;補充 A：Overthinking Tax——冗長輸出的經濟學接地（OckBench，arXiv:2511.05722）&quot;">​</a></h3><p><strong>對「加法思維是效率陷阱」主論點的硬數據佐證</strong>：本報告 §主論點主張「更少更精確 &gt; 更多」，但偏經驗法則。OckBench 給出可量化的經濟學證據——<strong>冗長有指數級成本懲罰</strong>。</p><p><strong>接地審計</strong>：</p><ul><li>Overthinking Tax / <code>57%</code> / <code>5.1×</code> ← &quot;the counterintuitive finding that smaller reasoning models can be more expensive than larger ones due to excessive token generation. A 7B open-source model is 57% more expensive than a 14B model when total cost (accuracy × token efficiency) is considered. Open-source models generate 5.1× more tokens than proprietary models&quot;（2025-11-07-ock-bench-reasoning-efficiency-overthinking-2511-05722.md L20）</li><li>OckScore 指數懲罰 ← &quot;<strong>OckScore penalizes verbosity exponentially</strong> — a model that doubles its token count must also significantly improve accuracy to maintain the same score.&quot;（同檔 L65）</li><li>5 個 overthinking 反模式（直接對應 output-discipline.md 禁令）← &quot;Unnecessary Verification Loops / Exhaustive Case Enumeration / Hedge Cascades / Pre-Answer Preamble / Post-Answer Elaboration&quot;（同檔 L115–L129）</li></ul><p><strong>啟示</strong>：output-discipline.md 的「無開場白 / 填充語禁止 / 精簡輸出」不只是風格偏好，而有<strong>可量化經濟學依據</strong>（Pre-Answer Preamble / Hedge Cascades 正是被禁的填充語）。⚠️ 57% / 5.1× 是「小開源推理模型 vs 大模型 / 專有模型」的對比，<strong>非</strong> Claude/Sonnet 自身數字；要點是「per-token 費率低 ≠ 總成本低」這個機制。</p><h3 id="補充-b-agentopt-ucb-e——a3「planner-solver-分離」的搜尋機制補完-arxiv-同-agentopt" tabindex="-1">補充 B：AgentOpt UCB-E——A3「planner/solver 分離」的搜尋機制補完（arXiv 同 AgentOpt） <a class="header-anchor" href="#補充-b-agentopt-ucb-e——a3「planner-solver-分離」的搜尋機制補完-arxiv-同-agentopt" aria-label="Permalink to &quot;補充 B：AgentOpt UCB-E——A3「planner/solver 分離」的搜尋機制補完（arXiv 同 AgentOpt）&quot;">​</a></h3><p><strong>對 §架構建議 A3 的直接補完</strong>：本報告 L78/L149 已引 AgentOpt 的「13–32× 成本差距」+「手工調優產生退化（−37%）」，主張最優邊界不應靠直覺手設。但缺「那要怎麼系統性搜」的答案。UCB-E 補上：</p><p><strong>接地審計</strong>：</p><ul><li><code>62–76%</code> ← &quot;The UCB-E algorithm achieves a 62–76% reduction in evaluation budget relative to brute-force search while recovering near-optimal accuracy.&quot;（2026-04-07-agentopt-client-side-optimization.md L22，再確認 L100）</li><li>模型須在 workflow 脈絡評估 ← &quot;optimal model combinations often differ from predictions based on standalone model capability rankings, demonstrating that models must be evaluated in workflow context, not isolation.&quot;（同檔 L22）</li></ul><p><strong>啟示</strong>：A3 的「planner/solver 最優分離邊界」可用 bandit（UCB-E）以 62–76% 更少評估預算找到，而非窮舉或手調。但 workspace 為 solo interactive，A3 仍標「複雜度高、未來 session」——UCB-E 是「若要系統化時的機制」，非立即行動。⚠️ 62–76% 是 v2 結果；v1 的 Arm Elimination 為 24–67%（同檔 L100），引用須標版本。</p><h3 id="補充-c-人寫-skill-遠勝自動學習——「人類-gate」是-simplicity-的一部分-skilllearnbench-arxiv-2604-20087" tabindex="-1">補充 C：人寫 skill 遠勝自動學習——「人類 gate」是 simplicity 的一部分（SkillLearnBench，arXiv:2604.20087） <a class="header-anchor" href="#補充-c-人寫-skill-遠勝自動學習——「人類-gate」是-simplicity-的一部分-skilllearnbench-arxiv-2604-20087" aria-label="Permalink to &quot;補充 C：人寫 skill 遠勝自動學習——「人類 gate」是 simplicity 的一部分（SkillLearnBench，arXiv:2604.20087）&quot;">​</a></h3><p><strong>對 skill 設計簡潔原則的實證</strong>：</p><p><strong>接地審計</strong>：</p><ul><li><code>10.17%</code> / <code>74.50%</code> / <code>~30%</code> ← &quot;Baseline (no skill): 10.17%. Human-authored skills: 74.50%. Automated skill-learning methods: ~30% (ceiling).&quot;（2026-04-22-skill-learn-bench-continual-skill-learning-2604-20087.md L20）</li><li>64.3pp ceiling gap ← &quot;The 74.50% → 10.17% gap (64.3pp) represents the current ceiling on automated skill learning&quot;（同檔 L46）</li><li>context-storage 抗遺忘 ← &quot;Context-storage skill representations (skills as markdown files) are catastrophic-forgetting-resistant by design.&quot;（同檔 L133）</li></ul><p><strong>啟示</strong>：① 與 SkillsBench「自生成 skill −1.3pp」（見 auto-load-token 報告補充 5）一致——<strong>workspace「人工建 skill + skill-evolution gate」決策獲雙論文背書</strong>；② skill-as-markdown（<code>.claude/skills/*.md</code>，context-storage）設計被證為抗 catastrophic-forgetting，無需 fine-tune。⚠️ 74.50% 是特定 benchmark 的 human-authored 上界，不可泛化為「人寫 skill 永遠 7×於自動」；要點是<strong>方向</strong>（人工 gate &gt; 全自動）。</p><h3 id="補充-d-ahe-observability——harness-改進需「結構化語意追蹤」非僅-logging-arxiv-2604-25850" tabindex="-1">補充 D：AHE observability——harness 改進需「結構化語意追蹤」非僅 logging（arXiv:2604.25850） <a class="header-anchor" href="#補充-d-ahe-observability——harness-改進需「結構化語意追蹤」非僅-logging-arxiv-2604-25850" aria-label="Permalink to &quot;補充 D：AHE observability——harness 改進需「結構化語意追蹤」非僅 logging（arXiv:2604.25850）&quot;">​</a></h3><p><strong>對 §架構建議 / 測試能力的補充</strong>：本報告以 healthcheck.sh 等手工 checklist 評 harness，但缺「系統性改進的可觀測性基礎」概念。</p><p><strong>接地審計</strong>：</p><ul><li><code>69.7% → 77.0%</code> ← &quot;ten AHE iterations improved pass@1 from 69.7% to 77.0%, surpassing human-designed baselines.&quot;（2026-04-30-ahe-observability-driven-harness-2604-25850.md L24）</li><li>跨模型遷移 ← &quot;Evolved harness transfers +5.1 to +10.1 pp gains across three alternative model families.&quot;（同檔 L24）</li><li>observability 定義 ← &quot;Observability is not just logging — it is structured semantic tracing that enables systematic harness improvement. Without observability, harness engineering is artisanal; with it, it becomes engineering.&quot;（同檔 L163）</li></ul><p><strong>啟示</strong>：呼應 autoload-evolution 閉環——harness 改進要可機械驗證（R4），「structured semantic tracing」是 OBSERVE 階段的學術接地。⚠️ 69.7→77.0% 是 Terminal-Bench 2 特定 benchmark + 10 iterations 的數字，非通用保證。</p><h3 id="既有「ace-簡潔有下限」段佐證-g13-非新條目" tabindex="-1">既有「ACE 簡潔有下限」段佐證（G13，非新條目） <a class="header-anchor" href="#既有「ace-簡潔有下限」段佐證-g13-非新條目" aria-label="Permalink to &quot;既有「ACE 簡潔有下限」段佐證（G13，非新條目）&quot;">​</a></h3><p>§「2026-06-05 增量併入」的 ACE brevity bias 段（簡潔有下限）獲<strong>第二篇獨立論文量化佐證</strong>：beyond-context-window（arXiv:2603.04814）實測 <strong>35:1 壓縮保留 broad topics 但失 specific facts / nuanced constraints</strong>——正是 ACE「drops domain insights」的具體化。</p><p><strong>接地審計</strong>：</p><ul><li><code>35:1</code> 失 nuance ← &quot;The 35:1 compression ratio preserves broad topics but loses specific facts and nuanced constraints — exactly the information that matters for accurate task completion.&quot;（2026-03-05-beyond-context-window-memory-vs-longcontext-2603-04814.md L91）</li><li>量化 + break-even ← &quot;Long-context … outperforms memory-based compression by 33.4–35.2 percentage points in accuracy. However, memory becomes economically favorable after approximately 10 conversation turns at 100K token context sizes.&quot;（同檔 L20）</li></ul><p><strong>啟示</strong>：強化「簡潔下限 = 保留 task-critical heuristics」——壓掉 nuanced constraints（如安全紅線、per-project 慣例）會傷準確率 33.4–35.2pp。這正是 autoload-slimming 報告「只壓 TYPE C/D rationale，不碰 TYPE A 行為條文」下限的外部接地。</p><p><em>增量併入日期：2026-06-05 | gap-vote 5 真 gap（OckBench / UCB-E / SkillLearnBench / AHE / 35:1-nuance）+ ACE 段佐證 | 全數主對話親自 grep 接地 | G13 掛既有 ACE 段非開新條目（語意去重）</em></p>',78)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
